/* From Uiverse.io by andrew-demchenk0 - Tags: checkbox, thumb, like */
.__UIV_SCOPE__ .container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.__UIV_SCOPE__ .container {
  display: block;
  position: relative;
  cursor: pointer;
  user-select: none;
}

.__UIV_SCOPE__ svg {
  position: relative;
  top: 0;
  left: 0;
  height: 50px;
  width: 50px;
  transition: all 0.3s;
  fill: #666;
}

.__UIV_SCOPE__ svg:hover {
  transform: scale(1.1) rotate(-10deg);
}

.__UIV_SCOPE__ .container input:checked ~ svg {
  fill: #2196F3;
}
